import {validation,integer} from '@crew/shared';
import {listIssues} from '../work/issues.js';
import {publicProject} from '../work/projects.js';
import {getSprint,getBurndown} from '../work/sprints.js';
import {publicActivity,canSeeActivity} from './activity.js';
import {issueMetrics,throughput,calendarDate} from './dashboard-metrics.js';
export function dashboard(ctx,req,query={}) {
  ctx.permissions.scope(req,'insight:read');
  if(!query.orgId)throw validation({orgId:'Choose an organization'});
  ctx.permissions.assertOrg(req,query.orgId,'org:read');
  const allowed=new Set(ctx.permissions.projectIds(req.user.id,query.orgId));
  if(query.projectId){
    const project=ctx.permissions.assertProject(req,query.projectId,'insight:read');
    if(project.org_id!==query.orgId)throw validation({projectId:'Choose a project in this organization'});
  }
  const projects=ctx.db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY name,id').all(query.orgId)
    .filter(project=>allowed.has(project.id)&&(!query.projectId||project.id===query.projectId))
    .map(row=>publicProject(ctx.db,row));
  const projectIds=new Set(projects.map(project=>project.id));
  const allIssues=projects.flatMap(project=>listIssues(ctx,project.id));
  const today=calendarDate(query.date??ctx.now().slice(0,10));
  const now=query.date?today+'T23:59:59.999Z':ctx.now();
  const priority=query.priority===undefined||query.priority===''?null:integer(query.priority,'priority',{min:0,max:4});
  const statuses=projects.flatMap(project=>project.statuses.map(status=>({...status,name:project.key+' · '+status.name})));
  if(query.statusId&&!statuses.some(status=>status.id===query.statusId))throw validation({statusId:'Choose a status from the current project scope'});
  if(query.overdue!==undefined&&!['true','false'].includes(query.overdue))throw validation({overdue:'Expected true or false'});
  const issues=allIssues.filter(issue=>!query.statusId||issue.statusId===query.statusId)
    .filter(issue=>!query.assigneeId||(query.assigneeId==='unassigned'?!issue.assigneeId:issue.assigneeId===query.assigneeId))
    .filter(issue=>priority===null||issue.priority===priority)
    .filter(issue=>query.overdue!=='true'||(issue.statusCategory!=='done'&&issue.dueDate&&issue.dueDate<today));
  const events=ctx.db.prepare("SELECT * FROM activity WHERE org_id=? AND entity_type='issue' ORDER BY created_at,id").all(query.orgId)
    .filter(row=>projectIds.has(row.project_id)&&canSeeActivity(ctx,req.user.id,row)).map(publicActivity);
  const sprintRows=ctx.db.prepare('SELECT id,project_id FROM sprints ORDER BY start_date DESC,created_at DESC,id').all()
    .filter(row=>projectIds.has(row.project_id));
  const sprints=sprintRows.map(row=>getSprint(ctx,row.id));
  let selected=null;
  if(query.sprintId){
    selected=sprints.find(sprint=>sprint.id===query.sprintId);
    if(!selected)throw validation({sprintId:'Choose a visible sprint in this dashboard'});
  }else selected=sprints.find(sprint=>sprint.status==='active')??sprints[0]??null;
  return {orgId:query.orgId,projectId:query.projectId??null,date:today,generatedAt:ctx.now(),projects,
    ...issueMetrics(issues,{today,statuses}),
    filters:{statusId:query.statusId??'',assigneeId:query.assigneeId??'',priority,overdue:query.overdue==='true'},
    issuePage:ctx.paginate(issues,{limit:query.issueLimit??20,cursor:query.issueCursor}),
    filterOptions:{statuses,assignees:[...new Map(allIssues.filter(issue=>issue.assigneeId).map(issue=>[issue.assigneeId,{id:issue.assigneeId,name:issue.assignee.name}])).values()]},
    throughput:throughput(events,{now,weeks:query.weeks??12}),
    sprints:sprints.map(sprint=>({id:sprint.id,projectId:sprint.projectId,name:sprint.name,status:sprint.status,startDate:sprint.startDate,endDate:sprint.endDate})),
    burndown:selected?getBurndown(ctx,selected.id):null};
}
export function registerDashboardRoutes(ctx) {
  ctx.app.get('/api/v1/dashboard',ctx.requireAuth,(req,res)=>res.json(dashboard(ctx,req,req.query)));
  ctx.app.get('/api/v1/projects/:projectId/dashboard',ctx.requireAuth,(req,res)=>{
    const project=ctx.permissions.assertProject(req,req.params.projectId,'insight:read');
    res.json(dashboard(ctx,req,{...req.query,orgId:project.org_id,projectId:project.id}));
  });
}

import {choice,text,fields,validation} from '@crew/shared';
import {listIssues,getIssue} from '../work/issues.js';
const kinds=['organizations','projects','issues','users'];
const permissions=['insight:read','project:read','export:read','issue:write'];
function queryId(value,field){return value===undefined||value===''?null:text(value,field,{max:128});}
function matches(item,query){return !query||(item.label+' '+item.description).toLocaleLowerCase().includes(query);}
function projectOption(row){return {id:row.id,label:row.key+' · '+row.name,description:row.description??'',key:row.key,name:row.name,orgId:row.org_id,archived:Boolean(row.archived)};}
function issueOption(issue){return {id:issue.id,label:issue.key+' · '+issue.title,description:issue.statusName+' · '+(issue.assignee?.name??'Unassigned'),key:issue.key,title:issue.title,projectId:issue.projectId,orgId:issue.orgId};}
export function entityOptions(ctx,req) {
  const input=fields(req.query,['type','permission','orgId','projectId','id','q','limit','cursor']);
  const type=choice(input.type,'type',kinds),permission=choice(input.permission,'permission',permissions,'insight:read');
  ctx.permissions.scope(req,'insight:read');
  ctx.permissions.scope(req,permission);
  const orgId=queryId(input.orgId,'orgId'),projectId=queryId(input.projectId,'projectId'),selectedId=queryId(input.id,'id');
  const q=text(input.q??'','q',{min:0,max:200}).toLocaleLowerCase();
  let items;
  if(type==='organizations') {
    ctx.permissions.scope(req,'org:read');
    items=ctx.db.prepare('SELECT o.*,m.role FROM organizations o JOIN memberships m ON m.org_id=o.id WHERE m.user_id=? ORDER BY o.name,o.id').all(req.user.id)
      .map(row=>({id:row.id,label:row.name,description:row.role,name:row.name,role:row.role}));
  }else{
    if(!orgId)throw validation({orgId:'Choose an organization first'});
    ctx.permissions.assertOrg(req,orgId,'org:read');
    if(projectId){const project=ctx.permissions.assertProject(req,projectId,permission);if(project.org_id!==orgId)throw validation({projectId:'Project belongs to another organization'});}
    if(type==='users') {
      items=ctx.db.prepare("SELECT u.id,u.name,u.email,m.role FROM users u JOIN memberships m ON m.user_id=u.id WHERE m.org_id=? AND m.role<>'guest' ORDER BY u.name,u.id").all(orgId)
        .map(row=>({id:row.id,label:row.name,description:row.email+' · '+row.role,name:row.name,email:row.email,role:row.role}));
    }else{
      const projects=ctx.db.prepare('SELECT * FROM projects WHERE org_id=? ORDER BY key,id').all(orgId)
        .filter(row=>(!projectId||row.id===projectId)&&ctx.permissions.canProject(req.user.id,row.id,'project:read')&&ctx.permissions.canProject(req.user.id,row.id,permission));
      if(type==='projects')items=projects.map(projectOption);
      else if(selectedId){
        const allowed=new Set(projects.map(row=>row.id));
        const row=ctx.db.prepare('SELECT project_id FROM issues WHERE id=?').get(selectedId);
        items=row&&allowed.has(row.project_id)?[issueOption(getIssue(ctx,selectedId))]:[];
      }else items=projects.flatMap(project=>listIssues(ctx,project.id)).map(issueOption).sort((a,b)=>a.key.localeCompare(b.key,undefined,{numeric:true})||a.id.localeCompare(b.id));
    }
  }
  const visible=items.filter(item=>selectedId?item.id===selectedId:matches(item,q));
  return {...ctx.paginate(visible,input),total:visible.length};
}
export function registerOptionRoutes(ctx) {
  ctx.app.get('/api/v1/insight/options',ctx.requireAuth,(req,res)=>res.json(entityOptions(ctx,req)));
}

import {validation,fields,choice,text} from '@crew/shared';
import {getIssue} from '../work/issues.js';
export function subscriptionTarget(ctx,req,type,targetId,permission='insight:read') {
  if (!['issue','project'].includes(type)) throw validation({targetType:'Choose issue or project'});
  const issue = type==='issue'?getIssue(ctx,targetId):null;
  const project = ctx.permissions.assertProject(req,issue?.projectId??targetId,permission);
  return {type,targetId,projectId:project.id,orgId:project.org_id,issue};
}
export function publicSubscription(row) {
  return {userId:row.user_id,orgId:row.org_id,projectId:row.project_id,targetType:row.target_type,
    targetId:row.target_id,manual:Boolean(row.manual),reason:row.reason,createdAt:row.created_at};
}
export function canReadProject(ctx,userId,projectId) {
  try { return ctx.permissions.canProject(userId,projectId,'insight:read'); }
  catch(error) { if(error.code==='NOT_FOUND')return false;throw error; }
}
export function subscribe(ctx,userId,target,reason='watch',manual=false) {
  if(!userId || !canReadProject(ctx,userId,target.projectId))return false;
  const existing=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(userId,target.type,target.targetId);
  if(existing?.reason==='muted'&&!manual)return false;
  ctx.db.prepare(`INSERT INTO subscriptions(user_id,org_id,project_id,target_type,target_id,manual,reason,created_at)
    VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(user_id,target_type,target_id) DO UPDATE SET
    manual=MAX(manual,excluded.manual),reason=CASE WHEN excluded.manual=1 THEN 'watch' ELSE subscriptions.reason END`)
    .run(userId,target.orgId,target.projectId,target.type,target.targetId,Number(manual),reason,ctx.now());
  return true;
}
export function automaticSubscriptions(ctx,event) {
  const item=event.after??event.before;
  const issue=event.entityType==='issue'?item:item?.issue;
  const issueId=issue?.id??event.issueId??item?.issueId;
  if(!event.projectId||!issueId)return {issueId:null,mentioned:[]};
  const target={type:'issue',targetId:issueId,orgId:event.orgId,projectId:event.projectId};
  if(issue) {
    subscribe(ctx,issue.createdBy,target,'creator');
    subscribe(ctx,issue.assigneeId,target,'assignee');
  }
  const mentioned=[...new Set([...(event.mentionedUserIds??[]),...(event.after?.mentionedUserIds??[]),...(event.after?.userIds??[])])];
  for(const userId of mentioned)subscribe(ctx,userId,target,'mention');
  return {issueId,mentioned};
}
export function registerSubscriptionRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    const rows=ctx.db.prepare("SELECT * FROM subscriptions WHERE user_id=? AND reason<>'muted' ORDER BY created_at DESC,target_id").all(req.user.id)
      .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
      .filter(row=>!req.query.projectId||row.project_id===req.query.projectId)
      .filter(row=>!req.query.targetType||row.target_type===req.query.targetType)
      .filter(row=>!req.query.targetId||row.target_id===req.query.targetId)
      .filter(row=>row.target_type!=='issue'||ctx.db.prepare('SELECT 1 FROM issues WHERE id=?').get(row.target_id))
      .filter(row=>canReadProject(ctx,req.user.id,row.project_id))
      .map(row=>{
        const target=row.target_type==='issue'?getIssue(ctx,row.target_id):ctx.db.prepare('SELECT * FROM projects WHERE id=?').get(row.target_id);
        const label=row.target_type==='issue'?target.key+' · '+target.title:target.key+' · '+target.name;
        return {...publicSubscription(row),id:row.target_type+':'+row.target_id,target:{id:row.target_id,label}};
      });
    res.json(ctx.paginate(rows,req.query));
  });
  app.post('/api/v1/subscriptions',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    fields(req.body,['targetType','targetId']);
    const type=choice(req.body.targetType,'targetType',['issue','project']);
    const targetId=text(req.body.targetId,'targetId',{max:128});
    const target=subscriptionTarget(ctx,req,type,targetId);
    const existing=ctx.db.prepare('SELECT 1 FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    if(existing)ctx.db.prepare("UPDATE subscriptions SET manual=1,reason='watch' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,type,targetId);
    else subscribe(ctx,req.user.id,target,'watch',true);
    const row=ctx.db.prepare('SELECT * FROM subscriptions WHERE user_id=? AND target_type=? AND target_id=?').get(req.user.id,type,targetId);
    res.status(201).json({subscription:publicSubscription(row)});
  });
  app.delete('/api/v1/subscriptions/:targetType/:targetId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');
    const target=subscriptionTarget(ctx,req,req.params.targetType,req.params.targetId);
    subscribe(ctx,req.user.id,target,'muted',true);
    ctx.db.prepare("UPDATE subscriptions SET manual=0,reason='muted' WHERE user_id=? AND target_type=? AND target_id=?").run(req.user.id,target.type,target.targetId);
    res.json({ok:true});
  });
}

import {useState} from 'preact/hooks';
import {Button} from '../../components/ui.jsx';
import {chartMaximum,lineSegments,countLabel} from './chart-data.js';
import {recordPage} from './record-browser-state.js';
export function BarChart({title,items,valueKey='count',labelKey='name',unit='issues',id='bar-chart',onSelect,selectedId}) {
  const [query,setQuery]=useState('');
  const [page,setPage]=useState(0);
  const result=recordPage(items,{query,page,size:15,columns:[{key:labelKey}]});
  const maximum=chartMaximum(items.map(item=>item[valueKey]));
  const height=Math.max(100,result.items.length*36+30);
  function choose(item){onSelect?.(item);}
  return <section className="chart-panel">
    <h2 id={id}>{title}</h2>
    <label>Find group <input type="search" value={query} onInput={event=>{setQuery(event.currentTarget.value);setPage(0);}}/></label>
    {!items.length?<p>No matching issues.</p>:<>
      <svg viewBox={'0 0 520 '+height} role="img" aria-labelledby={id}>
        {result.items.map((item,index)=>{
          const identifier=item.id??item.priority??index;
          return <g key={identifier} transform={'translate(0 '+(index*36+10)+')'} role={onSelect?'button':undefined} tabIndex={onSelect?0:undefined} aria-label={item[labelKey]+': '+countLabel(item[valueKey],unit)} onClick={()=>choose(item)} onKeyDown={event=>{if(onSelect&&['Enter',' '].includes(event.key)){event.preventDefault();choose(item);}}}>
            <text x="0" y="18" fontSize="12">{String(item[labelKey]??'Unassigned').slice(0,21)}</text>
            <rect x="165" y="2" width={item[valueKey]/maximum*290} height="24" fill={selectedId===identifier?'#a04d25':'#4263c7'}><title>{item[labelKey]}: {countLabel(item[valueKey],unit)}</title></rect>
            <text x={175+item[valueKey]/maximum*290} y="19" fontSize="12">{item[valueKey]}</text>
          </g>;
        })}
      </svg>
      <table><caption>{onSelect?'Choose a group to filter current issues.':'Current issue groups.'}</caption><thead><tr><th>Group</th><th>{unit==='points'?'Points':'Issues'}</th></tr></thead>
        <tbody>{result.items.map((item,index)=><tr key={item.id??item.priority??index}><td>{onSelect?<Button type="button" onClick={()=>choose(item)}>{item[labelKey]??'Unassigned'}</Button>:item[labelKey]??'Unassigned'}</td><td>{item[valueKey]}</td></tr>)}</tbody>
      </table>
      <p role="status">{result.from}–{result.to} of {result.total} groups</p>
      <div className="pagination"><Button type="button" disabled={!result.page} onClick={()=>setPage(result.page-1)}>Previous groups</Button><Button type="button" disabled={result.page+1>=result.pages} onClick={()=>setPage(result.page+1)}>Next groups</Button></div>
    </>}
  </section>;
}
export function LineChart({title,rows,series,id='line-chart',unit='points'}) {
  const maximum=chartMaximum(rows.flatMap(row=>series.map(item=>row[item.key])));
  const width=450,height=180;
  return <section className="chart-panel"><h2 id={id}>{title}</h2>{!rows.length?<p>No reporting history yet.</p>:<>
    <svg viewBox="0 0 530 250" role="img" aria-labelledby={id}>
      <g transform="translate(45 15)">
        {[0,.25,.5,.75,1].map(ratio=><g key={ratio}><line x1="0" x2={width} y1={height-height*ratio} y2={height-height*ratio} stroke="#d6deea"/><text x="-8" y={height-height*ratio+4} textAnchor="end" fontSize="11">{Math.round(maximum*ratio*10)/10}</text></g>)}
        {series.map(item=>lineSegments(rows,item.key,{width,height,maximum}).map((segment,index)=><g key={item.key+index}>
          <polyline fill="none" stroke={item.color} strokeWidth="2.5" strokeDasharray={item.dashed?'5 4':undefined} points={segment.map(point=>point.x+','+point.y).join(' ')}/>
          {segment.map(point=><circle key={point.date} cx={point.x} cy={point.y} r="3" fill={item.color}><title>{point.date}: {item.label} {point.value} {unit}</title></circle>)}
        </g>))}
        <text x="0" y="202" fontSize="11">{rows[0].date??rows[0].week}</text><text x={width} y="202" textAnchor="end" fontSize="11">{rows.at(-1).date??rows.at(-1).week}</text>
      </g>
    </svg><p>{series.map(item=><span key={item.key} style={{color:item.color,marginRight:'1rem'}}>● {item.label}</span>)}</p>
    <details><summary>Show chart data</summary><div className="table-scroll"><table><thead><tr><th>Date</th>{series.map(item=><th key={item.key}>{item.label}</th>)}</tr></thead><tbody>{rows.map(row=><tr key={row.date??row.week}><td>{row.date??row.week}</td>{series.map(item=><td key={item.key}>{row[item.key]===null?'Future':row[item.key]}</td>)}</tr>)}</tbody></table></div></details>
  </>}</section>;
}
